const Job = require('../models/Job');

/**
 * Helper to escape regex special characters
 */
function escapeRegex(text) {
  return text.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, '\\$&');
}

/**
 * Create a new job post
 */
async function createJob(data) {
  // Ensure postedDate is generated by server
  const jobPayload = {
    ...data,
    postedDate: new Date(),
  };

  const job = new Job(jobPayload);
  await job.save();
  return job;
}

/**
 * Get job by MongoDB ObjectId
 */
async function getJobById(id) {
  return await Job.findById(id);
}

/**
 * Query jobs with multi-field filtering, sorting, and pagination
 */
async function getJobs(filters = {}, page = 1, limit = 10) {
  const query = {};

  // Title search (regex case-insensitive)
  if (filters.title && filters.title.trim()) {
    query.title = { $regex: escapeRegex(filters.title.trim()), $options: 'i' };
  }

  // Company Name search (regex case-insensitive)
  if (filters.companyName && filters.companyName.trim()) {
    query.companyName = { $regex: escapeRegex(filters.companyName.trim()), $options: 'i' };
  }

  // Job Category (exact match)
  if (filters.jobCategory && filters.jobCategory.trim() && filters.jobCategory !== 'All') {
    query.jobCategory = filters.jobCategory.trim();
  }

  // Location Type (exact match: WFH | Hybrid | WFO)
  if (filters.locationType && filters.locationType.trim() && filters.locationType !== 'All') {
    query.locationType = filters.locationType.trim();
  }

  // City / Location search (for landing page dual search or specific city filter)
  if (filters.city && filters.city.trim()) {
    query.$or = [
      { city: { $regex: escapeRegex(filters.city.trim()), $options: 'i' } },
      { country: { $regex: escapeRegex(filters.city.trim()), $options: 'i' } },
    ];
  }

  // Skills filter (comma-separated string or array, $in any match)
  if (filters.skills) {
    let skillList = [];
    if (Array.isArray(filters.skills)) {
      skillList = filters.skills;
    } else if (typeof filters.skills === 'string') {
      skillList = filters.skills
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean);
    }

    if (skillList.length > 0) {
      // Case-insensitive regex match for each skill tag
      const skillRegexes = skillList.map((skill) => new RegExp(`^${escapeRegex(skill)}$`, 'i'));
      query.skills = { $in: skillRegexes };
    }
  }

  // Experience Range filters
  // A candidate asking for min X experience matches jobs whose experienceMax is at least X
  // A candidate asking for max Y experience matches jobs whose experienceMin is at most Y
  if (filters.experienceMin !== undefined && filters.experienceMin !== '' && !isNaN(filters.experienceMin)) {
    const minVal = Number(filters.experienceMin);
    query.experienceMax = { $gte: minVal };
  }

  if (filters.experienceMax !== undefined && filters.experienceMax !== '' && !isNaN(filters.experienceMax)) {
    const maxVal = Number(filters.experienceMax);
    query.experienceMin = { $lte: maxVal };
  }

  const safePage = Math.max(1, parseInt(page, 10) || 1);
  const safeLimit = Math.min(10, Math.max(1, parseInt(limit, 10) || 10));
  const skip = (safePage - 1) * safeLimit;

  const [total, jobs] = await Promise.all([
    Job.countDocuments(query),
    Job.find(query).sort({ postedDate: -1 }).skip(skip).limit(safeLimit).lean(),
  ]);

  const totalPages = Math.ceil(total / safeLimit) || 1;

  return {
    jobs,
    pagination: {
      total,
      page: safePage,
      limit: safeLimit,
      totalPages,
    },
  };
}

module.exports = {
  createJob,
  getJobById,
  getJobs,
};
